UPDATE `quest_template_locale` SET `QuestDescription` = 'Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь $gосторожен:осторожна;, нечестивое рвение делает их опасными противниками.' WHERE `ID` = 381 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь $gосторожен:осторожна;, нечестивое рвение делает их опасными противниками.' AS BINARY)));
