UPDATE `quest_template_locale` SET `QuestDescription` = 'Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Могильника на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье "Остывший очаг".' WHERE `ID` = 383 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Могильника на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье "Остывший очаг".' AS BINARY)));
