UPDATE `quest_template_locale` SET `QuestDescription` = 'Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой "инициативный", как ты, чтобы навсегда покончить с  Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей 10 воинов из Алого ордена.' WHERE `ID` = 427 AND `locale` = 'ruRU' AND (NOT (CAST(`QuestDescription` AS BINARY) <=> CAST('Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой "инициативный", как ты, чтобы навсегда покончить с  Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей 10 воинов из Алого ордена.' AS BINARY)));
